payload.raw:
{
  "title": "Database Index Performance Comparison",
  "intro": "A comparative analysis of common indexing structures based on performance characteristics. Scores are normalized on a scale of 1-10, where 10 represents the highest performance or efficiency.",
  "table": {
    "columns": [
      "Index Type",
      "Write Throughput",
      "Read Latency",
      "Storage Overhead"
    ],
    "rows": [
      {
        "Index Type": "B-Tree",
        "Write Throughput": 6,
        "Read Latency": 8,
        "Storage Overhead": 7
      },
      {
        "Index Type": "Hash Index",
        "Write Throughput": 9,
        "Read Latency": 10,
        "Storage Overhead": 4
      },
      {
        "Index Type": "LSM Tree",
        "Write Throughput": 10,
        "Read Latency": 5,
        "Storage Overhead": 6
      },
      {
        "Index Type": "Bitmap",
        "Write Throughput": 3,
        "Read Latency": 7,
        "Storage Overhead": 9
      }
    ]
  },
  "sections": [
    {
      "heading": "Metric Definitions",
      "points": [
        "Write Throughput: Ability to handle high-frequency insert/update operations.",
        "Read Latency: Speed of point lookups and range scans.",
        "Storage Overhead: Efficiency of disk space utilization relative to raw data."
      ]
    }
  ]
}

